def topological_sort(graph):
    visited = set()
    visiting = set()
    order = []

    def visit(node):
        if node in visiting:
            raise ValueError('cycle detected')
        if node in visited:
            return

        visiting.add(node)
        for dependency in graph.get(node, []):
            visit(dependency)

        visiting.remove(node)
        visited.add(node)
        order.append(node)

    # To ensure all nodes are accounted for, even those that 
    # only appear as dependencies and not as keys.
    all_nodes = set(graph.keys())
    for deps in graph.values():
        for d in deps:
            all_nodes.add(d)

    for node in all_nodes:
        if node not in visited:
            visit(node)

    return order
