import csv
import io

def parse_csv_line(line):
    if not line:
        return []
    # Use io.StringIO to treat the string as a file stream
    # csv.reader handles quoted fields and doubled quotes ("") automatically
    f = io.StringIO(line)
    reader = csv.reader(f)
    try:
        return next(reader)
    except StopIteration:
        return []
